<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_api_activity_create( WP_REST_Request $request ) { if ( ! function_exists( 'bp_activity_add' ) ) { return new WP_Error( 'buddypress_required', __( 'Activity is unavailable.', 'social-discovery-core' ), array( 'status' => 503 ) ); } if ( sd_core_rate_limited( 'activity_create', 12 ) ) { return new WP_Error( 'rate_limited', __( 'Please wait before posting again.', 'social-discovery-core' ), array( 'status' => 429 ) ); } $content = wp_kses_post( trim( (string) $request->get_param( 'content' ) ) ); if ( ! $content || mb_strlen( wp_strip_all_tags( $content ) ) > 1000 ) { return new WP_Error( 'invalid_content', __( 'Please enter a post under 1000 characters.', 'social-discovery-core' ), array( 'status' => 400 ) ); } $activity_id = bp_activity_add( array( 'user_id' => get_current_user_id(), 'content' => $content, 'component' => 'activity', 'type' => 'activity_update', 'hide_sitewide' => false ) ); return $activity_id ? rest_ensure_response( array( 'id' => absint( $activity_id ) ) ) : new WP_Error( 'activity_failed', __( 'The post could not be created.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
function sd_core_api_activity_comment( WP_REST_Request $request ) { if ( ! function_exists( 'bp_activity_new_comment' ) ) { return new WP_Error( 'buddypress_required', __( 'Comments are unavailable.', 'social-discovery-core' ), array( 'status' => 503 ) ); } if ( sd_core_rate_limited( 'activity_comment', 20 ) ) { return new WP_Error( 'rate_limited', __( 'Please wait before commenting again.', 'social-discovery-core' ), array( 'status' => 429 ) ); } $activity_id = absint( $request->get_param( 'activity_id' ) ); $content = sanitize_textarea_field( $request->get_param( 'content' ) ); if ( ! sd_core_activity_visible( $activity_id ) || ! $content ) { return new WP_Error( 'invalid_comment', __( 'That comment could not be added.', 'social-discovery-core' ), array( 'status' => 400 ) ); } $comment_id = bp_activity_new_comment( array( 'user_id' => get_current_user_id(), 'activity_id' => $activity_id, 'content' => $content, 'parent_id' => absint( $request->get_param( 'parent_id' ) ) ) ); return $comment_id ? rest_ensure_response( array( 'id' => absint( $comment_id ) ) ) : new WP_Error( 'comment_failed', __( 'The comment could not be added.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
function sd_core_api_activity_favorite( WP_REST_Request $request ) { $id = absint( $request->get_param( 'activity_id' ) ); if ( ! sd_core_activity_visible( $id ) || ! function_exists( 'bp_activity_favorite' ) ) { return new WP_Error( 'invalid_activity', __( 'That activity is unavailable.', 'social-discovery-core' ), array( 'status' => 404 ) ); } $favorite = filter_var( $request->get_param( 'favorite' ), FILTER_VALIDATE_BOOLEAN ); $result = $favorite ? bp_activity_favorite( $id ) : bp_activity_unfavorite( $id ); return $result ? rest_ensure_response( array( 'favorite' => $favorite ) ) : new WP_Error( 'favorite_failed', __( 'That action could not be saved.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
